create database techmart_analytics;
use techmart_analytics;

SET FOREIGN_KEY_CHECKS = 0;

DROP TABLE IF EXISTS order_status_log;
DROP TABLE IF EXISTS order_items;
DROP TABLE IF EXISTS orders;
DROP TABLE IF EXISTS products;
DROP TABLE IF EXISTS customers;
DROP TABLE IF EXISTS employees;
DROP TABLE IF EXISTS statuses;
DROP TABLE IF EXISTS regions;

SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================

-- DIMENSION TABLES -- 

CREATE TABLE regions (
    id          INT          NOT NULL,
    region_name VARCHAR(50)  NOT NULL,
    country     VARCHAR(50)  NOT NULL,
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE statuses (
    id           INT          NOT NULL,
    status_name  VARCHAR(50)  NOT NULL,
    description  VARCHAR(255),
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE employees (
    id            INT           NOT NULL,
    full_name     VARCHAR(100)  NOT NULL,
    role          VARCHAR(50),
    region_id     INT,
    hire_date     DATE,
    annual_salary DECIMAL(10,2),
    PRIMARY KEY (id),
    CONSTRAINT fk_emp_region FOREIGN KEY (region_id) REFERENCES regions(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE customers (
    id        INT          NOT NULL,
    full_name VARCHAR(100) NOT NULL,
    email     VARCHAR(100),
    city      VARCHAR(50),
    segment   VARCHAR(20),
    join_date DATE,
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE products (
    id           INT           NOT NULL,
    product_name VARCHAR(100)  NOT NULL,
    category     VARCHAR(50),
    subcategory  VARCHAR(50),
    unit_price   DECIMAL(10,2),
    cost_price   DECIMAL(10,2),
    PRIMARY KEY (id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


-- ============================================================
-- FACT TABLES -- 

CREATE TABLE orders (
    id                INT         NOT NULL,
    customer_id       INT,
    employee_id       INT,
    order_date        DATE,
    ship_date         DATE,
    delivery_date     DATE,
    current_status_id INT,
    PRIMARY KEY (id),
    CONSTRAINT fk_ord_customer FOREIGN KEY (customer_id)       REFERENCES customers(id),
    CONSTRAINT fk_ord_employee FOREIGN KEY (employee_id)       REFERENCES employees(id),
    CONSTRAINT fk_ord_status   FOREIGN KEY (current_status_id) REFERENCES statuses(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE order_items (
    id         INT           NOT NULL,
    order_id   INT,
    product_id INT,
    quantity   INT,
    unit_price DECIMAL(10,2),
    discount   DECIMAL(4,2),
    PRIMARY KEY (id),
    CONSTRAINT fk_item_order   FOREIGN KEY (order_id)   REFERENCES orders(id),
    CONSTRAINT fk_item_product FOREIGN KEY (product_id) REFERENCES products(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

CREATE TABLE order_status_log (
    id                  INT           NOT NULL,
    order_id            INT,
    status_id           INT,
    changed_at          DATETIME,
    changed_by_employee INT,
    notes               VARCHAR(300),
    PRIMARY KEY (id),
    CONSTRAINT fk_log_order    FOREIGN KEY (order_id)            REFERENCES orders(id),
    CONSTRAINT fk_log_status   FOREIGN KEY (status_id)           REFERENCES statuses(id),
    CONSTRAINT fk_log_employee FOREIGN KEY (changed_by_employee) REFERENCES employees(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;


